    ms' = MS (mkR (wz 0x0885a8) (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 (wz name) (wz size) (wz 0) (wz size) (wz 3) (wz 34) (Z_to_bv 64 (-1)) (wz 0) a6 (wz 222)
