             F (Z_to_bv 64 0x086c58) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp - 320, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
